function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  // Walk the level order: each real node owns the next two slots.
  let next = 1;
  let real = 1;
  for (let q = 0; q < real; q++) {
    for (let side = 0; side < 2 && next < root.length; side++) {
      if (root[next++] !== null) real++;
    }
  }
  if (next < root.length) return 'Some values in the level order have no parent.';
  const values = root.filter(v => v !== null);
  const n = values.length;
  if (n > 100) return 'The tree has at most 100 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > n)) return 'Each node holds between 0 and n coins.';
  if (values.reduce((a, b) => a + b, 0) !== n) return 'The coins must add up to the number of nodes.';
  return null;
}

