function distributeCoins(root) {
  // Every edge above a subtree must carry |coins in subtree - nodes in subtree| coins; sum that over all non-root nodes.
  const all = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    all.push(node);
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  let total = 0;
  for (const top of all) {
    if (top === root) continue;
    let coins = 0, count = 0;
    const queue = [top];
    for (let q = 0; q < queue.length; q++) {
      coins += queue[q].val;
      count++;
      if (queue[q].left) queue.push(queue[q].left);
      if (queue[q].right) queue.push(queue[q].right);
    }
    total += Math.abs(coins - count);
  }
  return total;
}

