function generate(rand, size) {
  const n = size === 'large' ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 10);
  // Build a random shape: sometimes a long chain, otherwise children attach to random free slots.
  const chainy = rand() < 0.25;
  const nodes = [{ val: 0, left: null, right: null }];
  const slots = [[0, 'left'], [0, 'right']];
  for (let i = 1; i < n; i++) {
    const k = chainy ? slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length)) : Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: 0, left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Hand out exactly n coins: all on one node, one each, or at random.
  const mode = rand();
  if (mode < 0.2) nodes[Math.floor(rand() * n)].val = n;
  else if (mode < 0.3) for (const node of nodes) node.val = 1;
  else {
    const hubs = 1 + Math.floor(rand() * Math.min(n, 4));
    const targets = Array.from({ length: hubs }, () => Math.floor(rand() * n));
    for (let c = 0; c < n; c++) nodes[rand() < 0.5 ? targets[Math.floor(rand() * hubs)] : Math.floor(rand() * n)].val++;
  }
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
